import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"单纯形","description":"","frontmatter":{"title":"单纯形","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simplex.md","filePath":"cs/simplex.md","lastUpdated":1789023840000}'),c={name:"cs/simplex.md"};function _(m,a,A,u,B,E){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="单纯形" tabindex="-1">单纯形 <a class="header-anchor" href="#单纯形" aria-label="Permalink to &quot;单纯形&quot;">​</a></h1><div class="epigraph"><p>线性规划的最优在顶点；单纯形沿基可行解走邻边，目标不减，直到检验数都非正。</p><footer>—— 据 Dantzig, Linear Programming and Extensions, 1963；CLRS 第 29 章整理</footer></div><p>上一课<a href="/cs/gaussian-elimination-xor-basis">高斯消元</a>解等式。线性规划（LP）：线性目标 + 线性不等式。缺口是单纯形：基、松弛变量、转轴。不重写消元的 \\(O(n^3)\\) 单次，转轴就是一次消元。后课对偶。Klee–Minty 最坏指数点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准形 \\(\\max c^\\top x\\)，\\(Ax=b\\)，\\(x\\ge 0\\)。基 \\(B\\)：\\(A_B\\) 可逆，\\(x_B=A_B^{-1}b\\ge 0\\)，非基为 0。目标用非基变量写，系数（检验数）全 \\(\\le 0\\) 则最优。否则选入基，比值检验选出基，转轴。有限顶点，若 degeneracy 须防循环（Bland）。</p><p>缺口是顶点游走，不是内点（后课）。多项式界不是单纯形最坏给出的——Khachiyan/Karmarkar 另路。</p><h3 id="不是整数规划" tabindex="-1">不是整数规划 <a class="header-anchor" href="#不是整数规划" aria-label="Permalink to &quot;不是整数规划&quot;">​</a></h3><p>顶点可以分数。整数约束下一课分支定界。不要把单纯形当 ILP 求解器。</p><p><span class="marginnote">Dantzig 单纯形。CLRS 29。Klee–Minty 1972 指数实例。后课弱对偶、强对偶、互补松弛。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>引入松弛变标准形。找初始基（两阶段或大 M）。循环转轴直到最优或无界（某列可无限增加）。</p>',11)),(e(),s(h,null,{default:i(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LP%5B%22LP%20%E6%A0%87%E5%87%86%E5%BD%A2%22%5D%20--%3E%20BFS%5B%22%E5%9F%BA%E5%8F%AF%E8%A1%8C%E8%A7%A3%22%5D%0A%20%20BFS%20--%3E%20RED%5B%22%E6%A3%80%E9%AA%8C%E6%95%B0%22%5D%0A%20%20RED%20--%3E%20PIV%5B%22%E8%BD%AC%E8%BD%B4%E9%82%BB%E9%A1%B6%E7%82%B9%22%5D%0A%20%20PIV%20--%3E%20BFS%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>实现用表或修正单纯形。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可行域多面体，最优可达顶点（有界时）。邻接转轴改一个基列。与最大流：网络单纯形是特例。与高斯：每个基解一次线性方程。目标沿正检验数方向升。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写椭球法证明。不写商业求解器预处理。后课默认：LP 顶点最优；单纯形实用、最坏可指数。下一课 LP 对偶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优在顶点；单纯形转轴改基。</li><li>最坏可指数；实践快。</li><li>分数解；整数要另法。</li><li>出处：Dantzig, 1963；CLRS 第 29 章。</li></ul>',7))])}const f=l(c,[["render",_]]);export{P as __pageData,f as default};
